    private static FractalCatalogItem Item(
        string[] categoryPath,
        string name,
        string description,
        string previewFile,
        string? launchKey = null) =>
        new(categoryPath, name, description, $"Assets/Previews/{previewFile}", launchKey ?? GetLaunchKey(previewFile));

